import{_ as s,o as e,c as n,a2 as i}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"Getting Started with FOSSBilling","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),t={name:"guide/getting-started.md"};function r(o,a,l,p,c,d){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="getting-started-with-fossbilling" tabindex="-1">Getting Started with FOSSBilling <a class="header-anchor" href="#getting-started-with-fossbilling" aria-label="Permalink to &quot;Getting Started with FOSSBilling&quot;">​</a></h1><p>Welcome to the <strong>FOSSBilling Next-Gen Ecosystem</strong>!</p><p>FOSSBilling is a modern, high-performance, open-source billing, subscription, and client management platform designed for web hosts, domain registrars, SaaS products, and digital agencies.</p><hr><h2 id="🌟-what-is-fossbilling" tabindex="-1">🌟 What is FOSSBilling? <a class="header-anchor" href="#🌟-what-is-fossbilling" aria-label="Permalink to &quot;🌟 What is FOSSBilling?&quot;">​</a></h2><p>FOSSBilling streamlines your entire recurring billing and cloud service provisioning pipeline:</p><ul><li><strong>Order Management &amp; Cart:</strong> Automated client checkout, promo codes, custom order forms, and fraud scoring.</li><li><strong>Automated Invoicing &amp; Subscriptions:</strong> Recurring invoice generation (14-day advance), tax rules, multiple currencies, and automatic overdue suspensions.</li><li><strong>Server &amp; Hosting Automation:</strong> Automatic provisioning and lifecycle management for cPanel, Plesk, DirectAdmin, HestiaCP, CentOS Web Panel (CWP), and custom webhooks.</li><li><strong>Domain Registration:</strong> Instant domain availability lookups, transfers, and DNS management via Namecheap, ResellerClub, Internet.bs, and custom providers.</li><li><strong>Customer Support Desk:</strong> Multi-department ticket management, threaded messages, file attachments, and automated ticket auto-close.</li></ul><hr><h2 id="🏛️-ecosystem-architecture" tabindex="-1">🏛️ Ecosystem Architecture <a class="header-anchor" href="#🏛️-ecosystem-architecture" aria-label="Permalink to &quot;🏛️ Ecosystem Architecture&quot;">​</a></h2><p>The platform is split into three decoupled, cloud-native services:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                   React Frontends                      │</span></span>
<span class="line"><span>│   • Administrator Portal (:3000) [Vite + Tailwind]     │</span></span>
<span class="line"><span>│   • Customer Client Portal (:3001) [Vite + Tailwind]   │</span></span>
<span class="line"><span>└──────────────────────────┬─────────────────────────────┘</span></span>
<span class="line"><span>                           │ HTTP REST JSON / OpenAPI 3.0</span></span>
<span class="line"><span>┌──────────────────────────▼─────────────────────────────┐</span></span>
<span class="line"><span>│                 Go Backend Engine (:8080)              │</span></span>
<span class="line"><span>│   • REST API Server (Clean Architecture)               │</span></span>
<span class="line"><span>│   • Background Worker Scheduler (Daemon)               │</span></span>
<span class="line"><span>│   • Terminal Administration Management CLI             │</span></span>
<span class="line"><span>└──────────────────────────┬─────────────────────────────┘</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>             ┌─────────────┴─────────────┐</span></span>
<span class="line"><span>             ▼                           ▼</span></span>
<span class="line"><span>    PostgreSQL 16 (Primary)       Redis 7 (Cache/Queue)</span></span></code></pre></div><hr><h2 id="🚀-quick-launch" tabindex="-1">🚀 Quick Launch <a class="header-anchor" href="#🚀-quick-launch" aria-label="Permalink to &quot;🚀 Quick Launch&quot;">​</a></h2><p>You can spin up the complete ecosystem in under 2 minutes using Docker:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Clone repository</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/damarkuncoro/FOSSBilling.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FOSSBilling</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Launch production stack</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/docker-compose.prod.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre></div><p>Access your portals:</p><ul><li><strong>Customer Portal:</strong> <a href="http://localhost:3001" target="_blank" rel="noreferrer"><code>http://localhost:3001</code></a> (<code>client@fossbilling.org</code> / <code>Password123!</code>)</li><li><strong>Administrator Portal:</strong> <a href="http://localhost:3000" target="_blank" rel="noreferrer"><code>http://localhost:3000</code></a> (<code>admin@fossbilling.org</code> / <code>admin123</code>)</li><li><strong>Go REST API &amp; Interactive Docs:</strong> <a href="http://localhost:8080/docs" target="_blank" rel="noreferrer"><code>http://localhost:8080/docs</code></a></li></ul><hr><h2 id="📖-operational-guides-next-steps" tabindex="-1">📖 Operational Guides &amp; Next Steps <a class="header-anchor" href="#📖-operational-guides-next-steps" aria-label="Permalink to &quot;📖 Operational Guides &amp; Next Steps&quot;">​</a></h2><p>Ready to set up your store and start serving clients? Follow our dedicated guides:</p><ul><li>📘 <strong><a href="/guide/step-by-step-guide">Complete Step-by-Step Usage Guide</a>:</strong> Comprehensive, phase-by-phase walkthrough covering Admin setup, payment gateways, server provisioning, product creation, customer ordering, automated provisioning, and ticket helpdesk.</li><li>⚙️ <strong><a href="/admin/overview">Administrator Guide</a>:</strong> Deep dive into administrative capabilities, currencies, products, and fraud prevention.</li><li>🛍️ <strong><a href="/client/overview">Customer Portal Guide</a>:</strong> Understand the client storefront, domain search, cart checkout, invoice management, and service control.</li><li>💻 <strong><a href="/guide/cli">CLI Management</a>:</strong> Learn how to run migrations, seeds, and background cron jobs from your terminal.</li></ul>`,21)])])}const u=s(t,[["render",r]]);export{g as __pageData,u as default};
